for ring in char_a_rings:
    draw_round_polyline(ring, width_units=w_text, color=DARK, closed=True)

for c_pts in (char_t1, char_t2, char_dot):
    polygon(c_pts, style=no_border_fill("#4E5868"))
    draw_round_polyline(c_pts, width_units=w_text, color=DARK, closed=True)

for ring in tokyo_rings:
    draw_round_polyline(ring, width_units=w_text, color=DARK, closed=True)
draw_compound_polygon(tokyo_rings, color="#4E5868")

save()
